import XCTest
import RepasteCore

/// Stage 11 — reflow golden tests. The input→expected pairs were derived by running the original JS
/// (Terminal Text Fixer, the source of truth for the behavior) as an oracle over each fixture.
final class ParagraphReflowerTests: XCTestCase {
    private let stage = ParagraphReflower()
    private func reflow(_ s: String) -> String { stage.apply(s, .default) }

    private let golden: [(name: String, input: String, expected: String)] = [
        ("prose_reflow", "The quick brown fox jumps over the lazy dog and then keeps\nrunning across the open field toward the distant treeline where\nthe sun is slowly setting behind the hills in the late evening.", "The quick brown fox jumps over the lazy dog and then keeps running across the open field toward the distant treeline where the sun is slowly setting behind the hills in the late evening."),
        ("prose_short_noreflow", "short one\nshort two\nshort three", "short one\nshort two\nshort three"),
        ("bullet_wrap", "- First item that is reasonably long and wraps onto the next\n  visual line because the terminal window is narrow over here\n- Second item is short", "- First item that is reasonably long and wraps onto the next visual line because the terminal window is narrow over here\n- Second item is short"),
        ("bullet_subitem", "- Parent item that is fairly long so the list stays in list mode\n   - child item indented by three spaces is a real sub item here", "- Parent item that is fairly long so the list stays in list mode\n- child item indented by three spaces is a real sub item here"),
        ("deep_continuation", "- Parent bullet item here that should remain a list item line\n   deep continuation text without any bullet marker present now", "- Parent bullet item here that should remain a list item line deep continuation text without any bullet marker present now"),
        ("inlist_exit_to_prose", "- short bullet\nthis is a following prose sentence that continues on the very\nnext line and should reflow together into a single prose line", "- short bullet\nthis is a following prose sentence that continues on the very next line and should reflow together into a single prose line"),
        ("false_bullet", "We should carefully consider whether to proceed toward Option\n1. The first reason is that it aligns with our broader goals.", "We should carefully consider whether to proceed toward Option 1. The first reason is that it aligns with our broader goals."),
        ("diff_block", "diff --git a/file.txt b/file.txt\n@@ -1,2 +1,2 @@\n- old line that was removed from the source file here\n+ new line that was added into the source file here", "diff --git a/file.txt b/file.txt\n@@ -1,2 +1,2 @@\n- old line that was removed from the source file here\n+ new line that was added into the source file here"),
        ("diff_indented_plus", "diff --git a/x b/x\n@@ -1,2 +1,2 @@\n- removed line here in the unified diff hunk output now\n+ added line here in the unified diff hunk output today\n   + indented continuation-looking line inside the hunk", "diff --git a/x b/x\n@@ -1,2 +1,2 @@\n- removed line here in the unified diff hunk output now\n+ added line here in the unified diff hunk output today\n   + indented continuation-looking line inside the hunk"),
        ("tui_block", "● Read(src/main.swift)\n  ⎿ Read 42 lines\n  │ some tui chrome content line goes here for testing\n  └ done reading the file contents now", "● Read(src/main.swift)\n  ⎿ Read 42 lines\n  │ some tui chrome content line goes here for testing\n  └ done reading the file contents now"),
        ("gutter_join", "   1  first source line of the file goes here today\n   2  second source line of the file goes here now\n   3  third source line continues across to another\n        line that wraps without any gutter number\n   4  fourth source line ends the listing block", "   1  first source line of the file goes here today\n   2  second source line of the file goes here now\n   3  third source line continues across to anotherline that wraps without any gutter number\n4  fourth source line ends the listing block"),
        ("indented_noreflow", "Traceback (most recent call last):\n    File \"app.py\", line 10, in <module>\n    File \"lib.py\", line 22, in handler\n    raise ValueError(\"the configured value was not valid here\")", "Traceback (most recent call last):\n    File \"app.py\", line 10, in <module>\n    File \"lib.py\", line 22, in handler\n    raise ValueError(\"the configured value was not valid here\")"),
        ("tabular_noreflow", "Name        Age    City and region of residence today\nAlice       30     London in the United Kingdom of GB\nBob         25     Paris in the country known as France", "Name        Age    City and region of residence today\nAlice       30     London in the United Kingdom of GB\nBob         25     Paris in the country known as France"),
        ("two_line_long", "This first line is definitely longer than thirty characters total\nand the second line is the paragraph remainder that follows it.", "This first line is definitely longer than thirty characters total and the second line is the paragraph remainder that follows it."),
        ("two_line_short", "short first line\nthis second line is much longer than the first one above it here", "short first line\nthis second line is much longer than the first one above it here"),
        ("unicode_threshold", "This paragraph contains unicode like → · § and 日本語 text that\nwraps onto a second visual line and should reflow into one 🎉", "This paragraph contains unicode like → · § and 日本語 text that wraps onto a second visual line and should reflow into one 🎉"),
        ("block1", "Here is a summary of the changes that were made to the code\nbase during this session and what each of them accomplishes\nfor the overall project going forward from this point onward.\n\nThe following items were completed during the work session:\n- Added the new authentication module that handles login and\n  also manages the refresh token rotation behind the scenes\n- Fixed the caching layer so that it no longer serves a stale\n  response to clients after an update has been published live\n- Wrote documentation for all of the public API endpoints\n\nThat should cover just about everything for the time being.", "Here is a summary of the changes that were made to the code base during this session and what each of them accomplishes for the overall project going forward from this point onward.\n\nThe following items were completed during the work session:\n- Added the new authentication module that handles login and also manages the refresh token rotation behind the scenes\n- Fixed the caching layer so that it no longer serves a stale response to clients after an update has been published live\n- Wrote documentation for all of the public API endpoints\n\nThat should cover just about everything for the time being."),
        ("block2", "Implementation plan for the upcoming release is broken into\nphases that each build on the previous one as listed below.\n- Phase one focuses on the data layer and the migrations that\n  are needed to support the new columns we are introducing now\n- Phase two wires the application services and the use cases\n  on top of the freshly migrated data layer from phase one\n- Phase three implements the infrastructure adapters that talk\n  to the outside world such as the clipboard and the hotkeys\n- Phase four builds the presentation layer including the menu\n  bar item and the small recorder window for the shortcut\n- Phase five is hardening and covers the edge cases plus the\n  accessibility prompts that the system may show to the user\n- Phase six handles distribution including signing as well as\n  the notarization recipe and the packaging for the download", "Implementation plan for the upcoming release is broken into phases that each build on the previous one as listed below.\n- Phase one focuses on the data layer and the migrations that are needed to support the new columns we are introducing now\n- Phase two wires the application services and the use cases on top of the freshly migrated data layer from phase one\n- Phase three implements the infrastructure adapters that talk to the outside world such as the clipboard and the hotkeys\n- Phase four builds the presentation layer including the menu bar item and the small recorder window for the shortcut\n- Phase five is hardening and covers the edge cases plus the accessibility prompts that the system may show to the user\n- Phase six handles distribution including signing as well as the notarization recipe and the packaging for the download"),
    ]

    func testMatchesJsOracle() {
        for c in golden {
            XCTAssertEqual(reflow(c.input), c.expected, "reflow diverged on fixture \(c.name)")
        }
    }

    func testIdempotentOverGolden() {
        for c in golden {
            let once = reflow(c.input)
            XCTAssertEqual(reflow(once), once, "not idempotent on fixture \(c.name)")
        }
    }
}
